<script setup lang="ts">
import {ref} from 'vue';
import {Modal,message} from 'ant-design-vue';
import http from '../api/http';
const emit=defineEmits<{changed:[]}>();
const base='/api/admin/v1/diary-presets/templates/';
const recycle=ref(false),rows=ref<any[]>([]),total=ref(0),page=ref(1),query=ref(''),busy=ref(false),error=ref(''),detail=ref<any>(null),reason=ref(''),title=ref('');
async function load(){busy.value=true;error.value='';try{const r:any=await http.get(base+'recycle-bin/',{params:{q:query.value,page:page.value}});rows.value=r.items;total.value=r.total;}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
function openBin(){recycle.value=true;page.value=1;void load();}
async function inspect(row:any){busy.value=true;error.value='';reason.value='';title.value='';try{detail.value=await http.get(base+row.id+'/delete-preview/');}catch(e:any){error.value=e.message;message.error(error.value);}finally{busy.value=false;}}
async function act(action:string){if(!detail.value||!reason.value.trim()||busy.value)return;busy.value=true;error.value='';try{await http.post(base+detail.value.id+'/'+action+'/',{revision:detail.value.revision,reason:reason.value.trim(),title:title.value,expected_preview_hash:detail.value.preview_hash});detail.value=null;emit('changed');message.success(action==='permanent-delete'?'模板已永久删除；共享文件保留':action==='trash'?'已移入回收站':'已恢复，保持下架状态');if(recycle.value)await load();}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
function confirm(action:string){Modal.confirm({title:action==='permanent-delete'?`永久删除「${detail.value.title}」？`:action==='trash'?'确认移入回收站？':'恢复模板并保持下架？',content:action==='permanent-delete'?'模板元数据不可恢复，操作将记录审计。':'仅处理当前环境，生产副本不会变化。',okText:action==='permanent-delete'?'永久删除':'确认',okType:action==='permanent-delete'?'danger':'primary',onOk:()=>act(action)});}
defineExpose({inspect,openBin});
</script>
<template>
<a-modal :open="recycle" title="模板回收站" :width="900" :footer="null" @cancel="recycle=false"><a-input-search v-model:value="query" placeholder="搜索已删除模板名称" @search="page=1;load()"/><a-alert v-if="error&&!detail" type="error" :message="error"/><a-table :data-source="rows" row-key="id" :loading="busy" :scroll="{x:650}" :pagination="{current:page,total,pageSize:20,showSizeChanger:false}" @change="(p:any)=>{page=p.current;load()}" :columns="[{title:'模板',dataIndex:'title'},{title:'系列',dataIndex:'series_title'},{title:'删除原因',dataIndex:'deletion_reason'},{title:'删除时间',key:'time'},{title:'操作',key:'action'}]"><template #bodyCell="{column,record}"><span v-if="column.key==='time'">{{new Date(record.deleted_at).toLocaleString('zh-CN')}}</span><a-button v-else-if="column.key==='action'" type="link" @click="inspect(record)">恢复 / 删除检查</a-button></template></a-table></a-modal>
<a-modal :open="!!detail" :title="detail?.title+' · 删除影响检查'" :width="700" :footer="null" :closable="!busy" :mask-closable="false" @cancel="detail=null"><template v-if="detail"><a-alert v-if="error" type="error" :message="error"/><a-alert type="info" show-icon :message="'当前环境：'+detail.environment" :description="detail.resource_note"/><a-descriptions bordered :column="2" style="margin:16px 0"><a-descriptions-item label="发布版本">{{detail.counts.versions}}</a-descriptions-item><a-descriptions-item label="用户添加记录">{{detail.counts.imports}}</a-descriptions-item><a-descriptions-item label="许可 / 订单">{{detail.counts.ownerships}} / {{detail.counts.orders}}</a-descriptions-item><a-descriptions-item label="配套包 / 关联">{{detail.counts.material_libraries}} / {{detail.counts.material_links}}</a-descriptions-item><a-descriptions-item label="上传 / 同步执行中">{{detail.counts.active_uploads}} / {{detail.counts.active_sync}}</a-descriptions-item><a-descriptions-item label="收费版本 / 草稿">{{detail.counts.pricing_versions}} / {{detail.counts.pricing_drafts}}</a-descriptions-item></a-descriptions><a-alert v-for="b in detail.blockers" :key="b" type="warning" :message="b" style="margin-bottom:8px"/><a-alert v-if="detail.can_purge" type="success" message="检查通过，可永久删除模板元数据"/><a-form layout="vertical" style="margin-top:20px"><a-form-item label="操作原因" required><a-textarea v-model:value="reason" :maxlength="500" :rows="2" placeholder="填写删除或恢复的原因"/></a-form-item><a-form-item v-if="detail.can_purge" label="永久删除确认：输入完整模板名称"><a-input v-model:value="title" :placeholder="detail.title"/></a-form-item></a-form><a-space wrap><a-button v-if="!detail.deleted_at" :disabled="!detail.can_trash||!reason.trim()||busy" @click="confirm('trash')">移入回收站</a-button><a-button v-else :disabled="!reason.trim()||busy" @click="confirm('restore-from-trash')">恢复并保持下架</a-button><a-button danger v-if="detail.can_purge" :disabled="title!==detail.title||!reason.trim()||busy" :loading="busy" @click="confirm('permanent-delete')">永久删除{{detail.quick_delete?'空草稿':''}}</a-button><a-button :disabled="busy" @click="inspect(detail)">重新检查</a-button></a-space></template></a-modal>
</template>
